(() => {
'use strict';
const $ = (s) => document.querySelector(s);
const screen = $('#screen'), tabs = $('#bottom-nav'), toastNode = $('#toast');
const I = (name, size) => `<svg aria-hidden="true"${size?` style="width:${size}px;height:${size}px"`:''}><use href="#i-${name}"/></svg>`;
const esc = (s='') => String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const doctors = [
  {id:'santos',name:'Dr. Andrea Santos',specialty:'General Physician',clinic:'Downtown Care Clinic · Davao City',area:'Poblacion, Davao City',years:'9 years',languages:'English, Filipino, Bisaya',photo:'assets/dr-cruz.svg',rating:'4.9',fee:650,soon:'Now · demo',status:'now',verified:true,about:'Supports everyday primary care, preventive health, and deciding when a referral to another specialist could be helpful.',schedule:{0:['Now','8:30 PM'],1:['9:30 AM','2:30 PM','4:00 PM'],2:['10:30 AM','3:00 PM']},modes:['Video','Voice','Text']},
  {id:'garcia',name:'Dr. Sofia Garcia',specialty:'General Physician',clinic:'Southside Community Clinic · Davao City',area:'Matina, Davao City',years:'6 years',languages:'English, Filipino, Bisaya',photo:'assets/dr-santos.svg',rating:'4.8',fee:550,soon:'Now · demo',status:'now',verified:true,about:'Provides first-contact consultations and patient-centered follow-up for common health concerns.',schedule:{0:['Now','9:00 PM'],1:['8:30 AM','1:30 PM'],2:['11:00 AM']},modes:['Video','Voice']},
  {id:'navarro',name:'Dr. Camille Navarro',specialty:'General Physician',clinic:'North Davao Primary Care · Davao City',area:'Bajada, Davao City',years:'8 years',languages:'English, Filipino, Bisaya',photo:'assets/dr-santos.svg',rating:'4.7',fee:600,soon:'Tomorrow · 11:00 AM',status:'later',verified:true,about:'Offers general medical consultations and helps patients find the right follow-up care.',schedule:{0:[],1:['11:00 AM','3:00 PM'],2:['9:30 AM']},modes:['Video','Text']},
  {id:'reyes',name:'Dr. Miguel Reyes',specialty:'Internal Medicine',clinic:'Bajada Family Health · Davao City',area:'Bajada, Davao City',years:'12 years',languages:'English, Filipino',photo:'assets/dr-reyes.svg',rating:'4.8',fee:800,soon:'Tomorrow · 10:30 AM',status:'later',verified:true,about:'Focuses on adult medical concerns and long-term health needs with an emphasis on clear explanations and follow-up.',schedule:{0:[],1:['10:30 AM','1:00 PM','3:30 PM'],2:['10:30 AM','4:30 PM']},modes:['Video','Voice']},
  {id:'lim',name:'Dr. Patricia Lim',specialty:'Pediatrics',clinic:'Matina Children’s Care · Davao City',area:'Matina, Davao City',years:'7 years',languages:'English, Filipino, Bisaya',photo:'assets/dr-santos.svg',rating:'4.9',fee:700,soon:'No online slots this week',status:'none',verified:true,about:'Provides child and adolescent consultations and family-centered healthcare guidance.',schedule:{},modes:['Video','Voice']}
];
const pharmacies = [
 {id:1,name:'Sample Pharmacy · Downtown',area:'Poblacion, Davao City',distance:'1.3 km',price:6.50,status:'Reported in stock',fresh:'Sample update · 2 hours ago',icon:'map-pin'},
 {id:2,name:'Sample Pharmacy · Bajada',area:'Bajada, Davao City',distance:'2.8 km',price:7.25,status:'Check with branch',fresh:'Sample update · 1 day ago',icon:'map-pin'},
 {id:3,name:'Sample Pharmacy · Matina',area:'Matina, Davao City',distance:'4.1 km',price:6.90,status:'Availability unconfirmed',fresh:'No recent update',icon:'map-pin'}
];
const s = {page:'home',history:[],hasSelectedDoctor:false,concern:'I’ve had a cough for a few days.',intakeStep:0,answers:{},doctorId:'santos',filter:'All',doctorQuery:'',doctorSearchOpen:false,medicineQuery:'Paracetamol 500 mg',medicine:'Paracetamol 500 mg',mapView:false,stockScenario:'mixed',dateOffset:0,time:'Now',mode:'Video',coverage:'self',lguStatus:'unverified',consent:false,booking:null,micOn:true,cameraOn:true,uploadName:null,scanDone:false,scanMedicine:'Paracetamol',scanStrength:'500 mg',scanQty:'10 tablets',askError:false,askBusy:false,onlyAvailable:false,careMode:'All',matchWindow:'now',availabilityFilter:'all',secureMessages:[{who:'doctor',text:'Welcome. This is a demonstration of the secure text consultation interface.'}]};
const getDoctor = () => doctors.find(d=>d.id===s.doctorId)||doctors[0];
const getSlots = (d,off=0) => (d.schedule&&d.schedule[off])||[];
const hasSlots = d => Object.values(d.schedule||{}).some(a=>a.length);
const isNow = d => getSlots(d,0).includes('Now');
const slotLabel = t => t==='Now'?'Now · demo':t;
const selectionLabel = () => s.time==='Now'?'As soon as possible · demo':`${formatDate(s.dateOffset)} · ${s.time}`;
const scheduleStatus = d => isNow(d)?tag('Available now · demo','green'):hasSlots(d)?tag('Next available · sample','neutral'):tag('No online slots','amber');
function selectDoctor(id,quick=false){const d=doctors.find(x=>x.id===id);if(!d)return;s.doctorId=d.id;s.dateOffset=isNow(d)?0:(getSlots(d,0).length?0:1);s.time=getSlots(d,s.dateOffset)[0]||'';s.mode=d.modes[0];s.coverage='self';s.lguStatus='unverified';s.hasSelectedDoctor=true;if(quick&&hasSlots(d))go('booking');else go('profile');}
const currency=(n)=>'₱'+n.toLocaleString('en-PH',{minimumFractionDigits:Number.isInteger(n)?0:2,maximumFractionDigits:2});
const appointmentDate=(offset=0)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return d;};
const formatDate=(off=0,options={weekday:'long',month:'short',day:'numeric'})=>appointmentDate(off).toLocaleDateString('en-PH',options);
const datePart=(off=0,part)=>appointmentDate(off).toLocaleDateString('en-PH',part==='day'?{weekday:'short'}:{day:'numeric'});
const backButton=()=>`<button class="round-icon" data-action="back" aria-label="Go back">${I('arrow-left')}</button>`;
const head=(t,right='')=>`<div class="view-head">${backButton()}<h1 class="view-title">${t}</h1>${right?`<div class="right-action">${right}</div>`:''}</div>`;
const section=(title,action='',page='')=>`<div class="section-label"><h2>${title}</h2>${action?`<button data-nav="${page}">${action} ${I('chevron-right')}</button>`:''}</div>`;
const tag=(text,type='')=>`<span class="pill-badge ${type}">${text}</span>`;
function btn(label,action,cls='full',extra=''){return `<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function navBtn(label,page,cls='full',icon=''){return `<button class="button ${cls}" data-nav="${page}">${label}${icon?I(icon):''}</button>`;}
function doctorCard(d){const slots=getSlots(d,0);return `<article class="doctor-card enhanced-card"><div class="doctor-upper"><img class="doctor-art" src="${d.photo}" alt="Illustrated sample portrait of ${esc(d.name)}"/><div class="grow"><div class="row" style="gap:5px;flex-wrap:wrap">${scheduleStatus(d)}</div><div class="doctor-name">${esc(d.name)}</div><div class="doctor-specialty">${esc(d.specialty)}</div><div class="doctor-sub">${I('map-pin')} ${esc(d.area)}</div></div></div><div class="doctor-slot-strip">${slots.length?slots.slice(0,3).map(t=>`<span class="time-preview">${esc(slotLabel(t))}</span>`).join(''):'No times currently shown in the demo'}</div><div class="doctor-lower"><div><div class="doctor-fee">${currency(d.fee)} <small>sample fee</small></div><div class="doctor-next">${isNow(d)?'Online consultation · sample':esc(d.soon)}</div></div><div class="row" style="gap:6px"><button class="button ghost small-btn" data-doctor="${d.id}" aria-label="View ${esc(d.name)} profile">Details</button>${hasSlots(d)?`<button class="button small-btn" data-quick-doctor="${d.id}" aria-label="Choose ${esc(d.name)}">Choose ${I('arrow-right')}</button>`:''}</div></div></article>`;}
function renderWelcome(){return `<div class="onboarding"><div class="onboarding-top"><div class="brand-lockup"><div class="brand-symbol"><span></span><span></span></div>E-JUAN</div><button data-nav="home" class="skip-link">Skip</button></div><div class="onboard-art"><div class="orb"><div class="core">${I('heart-pulse')}</div></div><div class="orbit-icon top">${I('stethoscope')}</div><div class="orbit-icon bottom">${I('message')}</div></div><div class="overline">ALAGANG ABOT-KAMAY</div><h1>Healthcare,<br/><em>made closer.</em></h1><p>Find the right kind of care, speak with a healthcare professional, and take your next step with confidence.</p><div class="feature-line">${I('check-circle')} Discover care with less guesswork</div><div class="feature-line">${I('check-circle')} Get guided help from Ask Juan</div><div class="feature-line">${I('check-circle')} Keep your care in one place</div><div class="onboarding-bottom">${navBtn(`Get started ${I('arrow-right')}`,'home')}<div class="disclaimer-small">Davao City · Interactive design concept</div></div></div>`;}
function renderHome(){return `<div class="view"><div class="home-header"><div><div class="loc-marker">${I('map-pin')} Davao City, Philippines ${I('chevron-down')}</div><div class="welcome">${greeting()}, Maria</div></div><button class="avatar-mini" data-nav="health" aria-label="My health">M</button></div><h1 class="home-title">Your health, a little<br/>easier to navigate.</h1><section class="hero-care"><div class="hero-tag">${I('sparkles')} MEET ASK JUAN</div><h2>Not sure where to start?</h2><p>Tell us what’s going on. We’ll help you explore your care options.</p><button data-nav="ask">Ask Juan ${I('arrow-right')}</button><div class="hero-drawing"><div class="draw-a"></div><div class="draw-b">${I('heart-pulse')}</div></div></section>${section('What would you like to do?')}<div class="two-cols"><button class="quick-card" data-nav="directory"><span class="quick-icon">${I('stethoscope')}</span><span class="quick-name">Find a doctor</span><span class="quick-desc">Explore care and available times</span></button><button class="quick-card" data-nav="pharmacies"><span class="quick-icon mint">${I('pill')}</span><span class="quick-name">Find medicines</span><span class="quick-desc">Compare sample pharmacies</span></button></div>${section(s.booking?'Your next step':'How it works',s.booking?'My health':'','health')}<button class="appointment-small" data-nav="${s.booking?'appointment':'ask'}"><div class="app-cal"><span>${datePart(s.booking?s.booking.dateOffset:4,'day')}</span><strong>${datePart(s.booking?s.booking.dateOffset:4,'num')}</strong></div><div class="grow"><div class="small strong">${s.booking?'Your consultation is booked':'Your care, at your pace'}</div><div class="tiny muted mt12" style="margin-top:5px">${s.booking?esc(s.booking.doctorName):'Ask Juan can help you get started'} · ${s.booking?s.booking.mode:'Care guidance'}</div><div class="tiny blue" style="margin-top:5px">${s.booking?s.booking.time:'Start whenever you like'} · ${s.booking?'Demo appointment':'Guided care discovery'}</div></div>${I('chevron-right')}</button>${section('Explore care options')}<button class="pathway-link" data-nav="coverageInfo"><span class="way-icon">${I('shield-check')}</span><span class="grow"><span class="small strong">Need help with care coverage?</span><span class="tiny muted" style="display:block;margin-top:4px;line-height:1.5">Understand YAKAP and LGU pathways</span></span>${I('chevron-right',15)}</button><p class="notice" style="margin:18px 0 0">Design demonstration only. Providers, availability, prices, coverage and records are fictional.</p></div>`;}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening';}
function composer(){return `<form class="ask-composer" id="ask-form"><div class="composer-card"><textarea id="ask-input" aria-label="Your question to Ask Juan" rows="2" placeholder="Tell Juan what’s on your mind..."></textarea><div class="composer-actions"><div class="row"><button type="button" class="flat-icon" data-action="ask-error" aria-label="Preview a connection issue" title="Preview connection issue">${I('plus')}</button><button type="button" class="flat-icon" data-action="voice" aria-label="Voice input demo">${I('mic')}</button></div><button type="submit" class="flat-icon send-btn" aria-label="Send question">${I('arrow-right')}</button></div></div><div class="ask-disclosure">Care navigation only · Not a medical diagnosis</div></form>`;}
function renderAsk(){return `<div class="ask-view"><div class="ask-head"><div class="row" style="gap:10px"><span class="ask-badge">${I('sparkles')}</span><span class="ask-head-title">Ask Juan</span></div><span class="quiet-tag">Your care guide</span></div>${s.askError?`<div class="ask-intro"><div class="error-illustration">${I('wifi')}</div><h1>We couldn't connect<br/>right now.</h1><p>Your message wasn't sent. Try again when your connection is stable, or browse healthcare options directly.</p><div class="action-stack mt20">${btn('Try again','ask-retry')}${navBtn('Browse doctors','directory','secondary')}</div></div>` :s.askBusy?`<div class="ask-intro"><div class="ask-logo">${I('sparkles')}</div><h1>Finding a helpful<br/>place to start.</h1><p>Preparing a few short questions to understand what kind of care to look for.</p><div class="card" style="width:100%"><div class="skeleton-line"></div><div class="skeleton-line short"></div><div class="skeleton-line"></div></div></div>`:`<div class="ask-intro"><div class="ask-logo">${I('sparkles')}</div><div class="eyebrow">YOUR CARE, ONE STEP AT A TIME</div><h1>Hi Maria. What can<br/>I help you with?</h1><p>You can tell me how you feel, look for care, or find a nearby pharmacy.</p><div class="starter-grid"><button data-starter="unwell">I don’t feel well</button><button data-starter="doctor">Find a doctor</button><button data-starter="medicine">Find a medicine</button><button data-starter="care">Help me find care</button></div></div>`}${composer()}</div>`;}
const questionSpecs=[
 {title:'Who needs care?',hint:'This helps us suggest a suitable starting point.',choices:['Myself','Someone else','Not sure']},
 {title:'How long has this been going on?',hint:'An approximate answer is fine.',choices:['Today','2–3 days','A week or longer','Not sure']},
 {title:'Any of these warning signs?',hint:'Choose the closest answer. If you may be in immediate danger, seek emergency help now.',choices:['None of these','Difficulty breathing','Chest pain','Fainting or confusion','Not sure']}
];
function renderDescribe(){return `<div class="view describe-view">${head('Ask Juan')}<span class="pill-badge">${I('sparkles')} START HERE</span><h1 class="page-h1" style="margin-top:19px">What's been going on?</h1><p class="page-lead">A sentence or two is enough. Juan will ask only a few relevant questions before helping you explore doctors.</p><form id="describe-form"><label for="describe-input" class="strong small" style="display:block;margin-bottom:10px">Tell us what you're experiencing</label><textarea id="describe-input" class="concern-input" rows="5" placeholder="For example: I've had a cough for the last three days."></textarea><div class="section-label" style="margin:19px 0 10px"><h2>Or start with an example</h2></div><div class="chip-row" style="flex-wrap:wrap;margin:0;padding:0">${[['Cough','I have had a cough for a few days'],['Headache','I have had a headache since yesterday'],['Stomach discomfort','My stomach has felt uncomfortable today']].map(([label,value])=>`<button type="button" class="chip" data-concern="${value}">${label}</button>`).join('')}</div><div class="info-box mt20">${I('info')} Juan is a care navigation assistant, not a doctor. For serious or sudden warning signs, seek urgent medical attention instead of waiting for an appointment.</div><div class="footer-actions"><button type="submit" class="button full">Continue ${I('arrow-right')}</button></div></form></div>`;}
function renderIntake(){const q=questionSpecs[Math.min(s.intakeStep,2)];const saved=Object.values(s.answers).map(a=>`<span class="answer-tag">${esc(a)}</span>`).join('');return `<div class="view"><div class="view-head">${backButton()}<h1 class="view-title">Ask Juan</h1><div class="right-action">${tag(`${s.intakeStep+1} of 3`,'neutral')}</div></div><div class="chat-body"><div class="user-bubble">${esc(s.concern)}</div><div class="ai-message"><span class="ai-avatar">${I('sparkles')}</span><div class="ai-text">I can help you find an appropriate care pathway. I'll ask a few short questions first.</div></div>${saved?`<div class="answered-context">${saved}</div>`:''}<div class="question-card"><div class="progress-dots">${[0,1,2].map((i)=>`<span class="${i<=s.intakeStep?'active':''}"></span>`).join('')}</div><h3>${q.title}</h3><p>${q.hint}</p><div class="option-stack">${q.choices.map((c)=>`<button class="answer-option" data-answer="${esc(c)}">${esc(c)} ${I('chevron-right')}</button>`).join('')}</div></div><div style="margin-left:36px">${btn('I need urgent help','emergency','ghost small-btn')}</div></div><div style="flex:1;min-height:45px"></div><div class="footer-actions"><div class="info-box">${I('info')} Ask Juan offers navigation guidance, not a diagnosis or a substitute for a clinician.</div></div></div>`;}
function renderRecommendation(){const recommended=doctors.filter(d=>d.specialty==='General Physician'&&hasSlots(d));const matches=s.matchWindow==='now'?recommended.filter(isNow):recommended;return `<div class="view match-view">${head('Ask Juan · Care matches')}<div class="ai-match-intro"><span class="ai-avatar">${I('sparkles')}</span><div class="grow"><span class="tiny blue strong">JUAN'S SUGGESTION</span><h1>Here are doctors who may help.</h1><p>Based on your answers, a <strong>general physician</strong> may be a suitable first point of contact. You can choose someone available now or browse upcoming times.</p></div></div><div class="match-context"><div class="row between"><div class="small strong">Your care request</div><button class="text-button" data-action="edit-answers">Edit</button></div><p>${esc(s.concern)}</p><div class="answered-context" style="margin:8px 0 0">${Object.values(s.answers).map(a=>`<span class="answer-tag">${esc(a)}</span>`).join('')}</div></div><div class="row between" style="margin:22px 0 10px"><div><h2 class="match-heading">Choose your doctor</h2><p class="tiny muted" style="margin:5px 0 0">${matches.length} shown · fictional availability</p></div>${tag(`${I('calendar')} Sample data`,'neutral')}</div><div class="availability-tabs" role="group" aria-label="Doctor availability"><button class="${s.matchWindow==='now'?'active':''}" data-match-window="now">${I('check-circle')} Available now <span>2</span></button><button class="${s.matchWindow==='all'?'active':''}" data-match-window="all">All times</button></div>${matches.length?matches.map(d=>doctorCard(d)).join(''):`<div class="card"><div class="small strong">No one available for that time</div><p class="small muted">Try upcoming times or browse the full directory.</p>${btn('See upcoming times','show-upcoming','secondary full')}</div>`}<button class="full-directory-link" data-nav="directory">Browse all doctors and specialties ${I('arrow-right')}</button><div class="info-box mt12">${I('info')} Ask Juan helps you navigate care, not diagnose illness. These are fictional doctors and sample time slots; a real app would verify availability before booking.</div></div>`;}
function renderEmergency(){return `<div class="view">${head('Urgent care guidance')}<div class="error-illustration" style="margin:21px 0 20px;background:var(--danger-bg);color:var(--danger);width:72px;height:72px">${I('alert-triangle')}</div><h1 class="page-h1">Please seek urgent<br/>medical help.</h1><p class="page-lead">Some symptoms you described may need immediate attention. Don't wait for a routine appointment or an AI response.</p><div class="card" style="border-color:var(--danger-line);background:var(--danger-bg)"><div class="row" style="margin-bottom:12px">${I('phone',20)} <strong style="font-size:14px">Philippines emergency hotline: 911</strong></div><p style="font-size:12px;color:var(--ink2);line-height:1.75;margin:0">If you are in immediate danger, call emergency services or go to the nearest emergency department. Ask someone nearby for help if needed.</p></div><div class="action-stack mt20"><a class="button full danger" href="tel:911">${I('phone')} Call 911</a>${navBtn('Back to home','home','ghost')}</div><button class="text-button mt20" data-action="edit-answers">I selected the wrong answer</button><div class="info-box red mt20">${I('info')} E-JUAN does not provide emergency monitoring or medical diagnosis.</div></div>`;}
function renderDirectoryResults(){let ds=doctors.filter(d=>(s.filter==='All'||d.specialty===s.filter)&&(!s.onlyAvailable||hasSlots(d))&& (s.careMode==='All'||d.modes.includes(s.careMode)) && (`${d.name} ${d.specialty} ${d.area}`.toLowerCase().includes(s.doctorQuery.toLowerCase())) &&(s.availabilityFilter==='all'||(s.availabilityFilter==='now'?isNow(d):(hasSlots(d)&&!isNow(d)))));return `<div class="result-count"><strong>${ds.length} ${ds.length===1?'doctor':'doctors'} shown</strong><span>${I('map-pin',13)} Davao City · Demo</span></div>${ds.length?ds.map(d=>doctorCard(d)).join(''):`<div class="empty-graphic">${I('calendar')}</div><h2 class="empty-h">No matching times</h2><p class="empty-p">Try an upcoming appointment, another specialty, or reset the filters.</p>${btn('Clear filters','clear-filters','secondary full')}`}<p class="notice" style="margin-top:14px">All clinicians, status badges, fees, and schedules are fictional sample data. No appointments are held or reserved.</p>`;}
function renderDirectory(){return `<div class="view">${head('Find care',`<button class="round-icon" data-nav="coverageInfo" aria-label="Care eligibility information">${I('shield-check')}</button>`)}<h1 class="page-h1">Find a doctor<br/>who fits your time.</h1><p class="page-lead">Explore available doctors, compare care options, and choose a consultation time.</p><form id="doctor-search-form" class="directory-search-control ${s.doctorSearchOpen?'is-open':''}"><button type="button" class="directory-search-toggle" data-action="doctor-search-toggle" aria-label="${s.doctorSearchOpen?'Hide doctor search':'Open doctor search'}" aria-expanded="${s.doctorSearchOpen}" aria-controls="doctor-search-field">${I('search')}</button><div class="directory-search-field" id="doctor-search-field" ${s.doctorSearchOpen?'':'hidden'}><input id="doctor-search-input" name="query" value="${esc(s.doctorQuery)}" aria-label="Search doctors" placeholder="Name, specialty, or location" autocomplete="off"/><button type="submit" class="search-submit" aria-label="Search">${I('arrow-right',16)}</button></div><div class="availability-tabs" role="group" aria-label="Availability filters">${[['all','All'],['now','Available now'],['later','Upcoming']].map(([val,label])=>`<button type="button" data-availability-filter="${val}" class="${s.availabilityFilter===val?'active':''}">${label}</button>`).join('')}</div></form><div class="chip-row mt12">${['All','General Physician','Internal Medicine','Pediatrics'].map(f=>`<button class="chip ${s.filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="chip-row" style="margin-top:8px">${['All','Video','Voice','Text'].map(f=>`<button class="chip ${s.careMode===f?'selected':''}" data-care-mode="${f}">${f==='All'?'Any mode':f}</button>`).join('')}</div><div id="doctor-results" class="directory-results">${renderDirectoryResults()}</div></div>`;}
function renderProfile(){const d=getDoctor(),slots=getSlots(d,s.dateOffset);return `<div class="view">${head('Doctor profile',`<button class="round-icon" data-action="share" aria-label="Share profile">${I('external-link')}</button>`)}<div class="doctor-profile-hero"><img class="profile-art" src="${d.photo}" alt="Illustrated fictional clinician portrait"/><div class="grow">${scheduleStatus(d)}<h1 class="profile-name">${esc(d.name)}</h1><div class="small muted">${esc(d.specialty)}</div><div class="row" style="margin-top:13px;gap:7px">${tag(`${I('star')} ${d.rating} · demo rating`,'amber')}</div></div></div><div class="profile-stats"><div><strong>${d.years.split(' ')[0]}</strong><span>Years practicing</span></div><div><strong>${d.modes.length}</strong><span>Care modes</span></div><div><strong>${currency(d.fee)}</strong><span>Sample fee</span></div></div><div class="profile-section"><h3>About</h3><p>${d.about}</p></div><div class="profile-section"><h3>Clinic & details</h3><div class="row" style="margin:11px 0">${I('map-pin',17)}<div class="small muted">${esc(d.clinic)}</div></div><div class="row">${I('message',17)}<div class="small muted">${esc(d.languages)}</div></div></div><div class="profile-section"><div class="row between"><h3>Choose an available time</h3><span class="tiny muted">Sample slots</span></div>${hasSlots(d)?`<div class="date-pills">${[0,1,2,3,4,5].map(off=>`<button class="date-pill ${s.dateOffset===off?'selected':''}" data-date="${off}"><span>${datePart(off,'day')}</span><strong>${datePart(off,'num')}</strong></button>`).join('')}</div>${slots.length?`<div class="time-grid">${slots.map(t=>`<button class="slot ${s.time===t?'selected':''}" data-time="${t}">${esc(slotLabel(t))}</button>`).join('')}</div>`:`<div class="info-box amber mt12">${I('calendar')} No sample appointments on this date. Pick another day or doctor.</div>`}`:`<div class="info-box amber">${I('calendar')} No sample online times currently listed. You can browse other doctors.</div>`}</div><div class="footer-actions">${hasSlots(d)?`<button class="button full" data-nav="booking" ${slots.length?'':'disabled'}>Continue with ${esc(d.name.split(' ').slice(1).join(' '))} ${I('arrow-right')}</button>`:navBtn('Explore other doctors','directory','secondary')}<div class="disclaimer-small">Fictional clinician and sample schedule. Final eligibility is checked later.</div></div></div>`;}
function coverageCard(type,icon,title,desc,foot){return `<button class="coverage-card ${s.coverage===type?'active':''}" data-coverage="${type}" style="width:100%;text-align:left"><span class="choice-radio"></span><span class="top-icon ${type==='lgu'?'green':''}">${I(icon)}</span><h3>${title}</h3><p>${desc}</p><div class="card-foot">${foot}</div></button>`;}
function renderCoverage(){if(!s.hasSelectedDoctor)return renderCoverageInfo();const d=getDoctor();return `<div class="view">${head('Care options')}<div class="journey-progress"><span><strong>Step 2 of 3</strong> · Care options</span><span>Review next</span></div><h1 class="page-h1">Let's check your<br/>care options.</h1><p class="page-lead">You can book standard care without verifying any benefit. Sponsored consultations are only for selected, approved beneficiaries.</p>${s.time?`<div class="care-selection-summary">${I('calendar',17)} <span>${esc(d.name)}<br/><small>${esc(selectionLabel())} · ${esc(s.mode)}</small></span><button class="text-button" data-nav="booking">Edit</button></div>`:''}${coverageCard('self','user','Standard consultation',`Continue with the sample fee shown. No LGU approval required.`,`Estimated cost · ${currency(d.fee)}`)}${coverageCard('lgu','shield-check','LGU-funded consultation','For selected beneficiaries only, after the program, provider, service and available budget are all approved.',s.lguStatus==='approved'?'Approved scenario · ₱0 demo':s.lguStatus==='pending'?'Demo status · Pending checks':'Approval required · Not verified')}${coverageCard('yakap','heart-pulse','PhilHealth YAKAP primary care','A separate pathway through an applicable accredited primary-care clinic, subject to its rules and available services.','Not an automatic subsidy for this online booking')}${s.coverage==='lgu'?`<div class="test-tools"><div class="overline">PROTOTYPE ONLY · PREVIEW BENEFICIARY STATES</div><p>These are fictional outcomes to test the experience—not a real eligibility lookup. Funding approval is never inferred from membership alone.</p><div class="chip-row">${[['unverified','Not verified'],['pending','Pending'],['approved','Approved demo']].map(([v,l])=>`<button class="chip ${s.lguStatus===v?'selected':''}" data-lgu="${v}">${l}</button>`).join('')}</div></div>${s.lguStatus==='pending'?`<div class="info-box amber mt12">${I('clock')} This sample beneficiary's checks are pending. Funded booking is unavailable for now; standard care can continue.</div>`:''}${s.lguStatus==='approved'?`<div class="info-box green mt12">${I('check-circle')} Fictional beneficiary, consultation and budget checks are approved for this sample booking only.</div>`:''}${s.lguStatus==='unverified'?`<div class="info-box mt12">${I('info')} This sample user is not verified as a funded beneficiary. You can still book standard care.</div>`:''}`:''}${s.coverage==='yakap'?`<div class="info-box amber mt12">${I('info')} YAKAP is handled by applicable accredited primary-care clinics. This prototype does not verify clinic arrangements.</div>`:''}<div class="footer-actions">${s.coverage==='yakap'?btn('See YAKAP next steps','yakap-next'):s.coverage==='lgu'&&s.lguStatus!=='approved'?btn('Continue with standard booking','coverage-self-review'):btn('Review consultation','to-review')}</div></div>`;}
function renderBooking(){const d=getDoctor(),slots=getSlots(d,s.dateOffset);return `<div class="view">${head('Choose consultation')}<div class="journey-progress"><span><strong>Step 1 of 3</strong> · Doctor & time</span><span>Care options next</span></div><div class="review-doctor"><img src="${d.photo}" alt=""/><div><div class="small strong">${esc(d.name)}</div><div class="tiny muted mt12" style="margin-top:5px">${esc(d.specialty)}</div><div class="tiny" style="margin-top:7px">${scheduleStatus(d)}</div></div><button data-nav="directory" class="text-button" style="margin-left:auto">Change</button></div>${section('How would you like to talk?')}<div class="consultation-modes">${[['Video','video'],['Voice','phone'],['Text','message']].filter(([m])=>d.modes.includes(m)).map(([m,ic])=>`<button class="mode-card ${s.mode===m?'active':''}" data-mode="${m}">${I(ic)}<span>${m}</span></button>`).join('')}</div>${section('Choose a day')}<div class="date-pills">${[0,1,2,3,4,5,6].map(off=>`<button class="date-pill ${s.dateOffset===off?'selected':''}" data-date="${off}"><span>${off===0?'Today':datePart(off,'day')}</span><strong>${datePart(off,'num')}</strong></button>`).join('')}</div>${section('Available time slots')} ${slots.length?`<div class="time-grid">${slots.map(t=>`<button class="slot ${s.time===t?'selected':''}" data-time="${t}">${esc(slotLabel(t))}</button>`).join('')}</div>`:`<div class="info-box amber">${I('clock')} No sample slots for this day. Try another date or choose a different doctor.</div>`}<div class="card soft mt20"><div class="row between"><div><div class="tiny muted mb8">Standard consultation fee · sample</div><div class="booking-price">${currency(d.fee)}</div></div>${I('shield-check',22)}</div><p class="small muted" style="line-height:1.65;margin:9px 0 0">Eligible selected beneficiaries may have this fee covered by an approved LGU program. We'll check your care options next—nothing is assumed.</p></div><div class="footer-actions">${btn('Continue to care options','to-coverage','full',slots.length?'':'disabled')}<div class="disclaimer-small">No live provider schedule or payment is connected</div></div></div>`;}
function renderReview(){const d=getDoctor(),free=s.coverage==='lgu'&&s.lguStatus==='approved';return `<div class="view">${head('Review booking')}<div class="journey-progress"><span><strong>Step 3 of 3</strong> · Review</span><span>Almost done</span></div><h1 class="page-h1">One last check.</h1><p class="page-lead">Review your consultation, chosen care pathway, and optional Ask Juan summary.</p><div class="summary-review"><div class="review-doctor"><img src="${d.photo}" alt=""/><div><div class="strong small">${esc(d.name)}</div><div class="tiny muted" style="margin-top:5px">${esc(d.specialty)} · ${esc(d.area)}</div></div></div><div class="kv"><span class="key">Date</span><span class="value">${s.time==='Now'?'Today · immediate demo':formatDate(s.dateOffset)}</span></div><div class="kv"><span class="key">Time</span><span class="value">${esc(slotLabel(s.time))}</span></div><div class="kv"><span class="key">Consultation</span><span class="value">${esc(s.mode)}</span></div><div class="kv"><span class="key">Care pathway</span><span class="value">${free?'Approved LGU demo':'Standard booking'}</span></div><div class="subtle-line"></div><div class="kv"><span class="key strong">Sample total</span><span class="booking-price" style="font-size:21px">${free?'₱0':currency(d.fee)}</span></div>${free?`<div class="info-box green mt12">${I('check-circle')} Funding is applied only in this fictional pre-approved beneficiary scenario.</div>`:''}</div><div class="card mt12"><div class="row between"><span class="strong small">Optional Ask Juan handoff</span>${tag('Your choice','neutral')}</div>${Object.keys(s.answers).length?`<p class="small muted" style="line-height:1.6;margin:12px 0 0">${esc(s.concern)}</p><div class="answered-context" style="margin:8px 0">${Object.values(s.answers).map(a=>`<span class="answer-tag">${esc(a)}</span>`).join('')}</div><button class="text-button" data-action="edit-answers">Review or change answers ${I('arrow-right',13)}</button><label class="checkbox-line"><input type="checkbox" id="consent-box" ${s.consent?'checked':''}/><span>I've reviewed the summary and agree to share it with the clinician. This is optional.</span></label>`:`<p class="tiny muted" style="line-height:1.7;margin:10px 0 0">You can book without using Ask Juan or sharing an AI-generated handoff.</p>`}</div><div class="info-box mt12">${I('lock')} This preview doesn't transmit patient records. Real bookings would require secure identity and availability confirmation.</div><div class="footer-actions">${btn('Confirm sample booking','confirm-booking')}<div class="disclaimer-small">Nothing will be charged and no doctor contacted</div></div></div>`;}
function renderBooked(){const b=s.booking;return `<div class="view"><div class="success-disc">${I('check')}</div><h1 class="success-title">You're all set.</h1><p class="success-note">Your sample appointment is confirmed inside this prototype. No real provider was contacted.</p><div class="receipt-card"><div class="row between"><div class="receipt-label">SAMPLE BOOKING</div>${tag(`${I('check-circle')} Confirmed`,'green')}</div><h3 style="margin:15px 0 5px;font-size:18px;letter-spacing:-.5px">${esc(b.doctorName)}</h3><div class="tiny muted">${esc(b.mode)} consultation</div><div class="subtle-line"></div><div class="row" style="margin:12px 0">${I('calendar',18)} <span class="small">${formatDate(b.dateOffset)}</span></div><div class="row">${I('clock',18)} <span class="small">${esc(slotLabel(b.time))}</span></div><div class="subtle-line"></div><div class="row between"><span class="small muted">Estimated total</span><strong>${currency(b.fee)}</strong></div></div><div class="action-stack mt20">${navBtn('View appointment','appointment')}${navBtn('Return home','home','ghost')}</div></div>`;}
function renderAppointment(){const b=s.booking||{doctorName:'Dr. Andrea Santos',doctorId:'santos',dateOffset:4,time:'Now',mode:'Video',fee:650};const d=doctors.find(d=>d.id===b.doctorId)||doctors[0];return `<div class="view">${head('Appointment details')}<div class="row" style="margin:4px 0 19px">${tag(`${I('check-circle')} ${s.booking?'Confirmed demo':'Example appointment'}`,'green')}</div><div class="card"><div class="row top"><img src="${d.photo}" class="doctor-art" alt="" style="height:105px;width:93px"/><div class="grow"><div class="doctor-name">${esc(b.doctorName)}</div><div class="doctor-specialty">${esc(d.specialty)}</div><div class="doctor-sub">${I('map-pin')} Davao City</div><span class="pill-badge mt12">${I('video')} ${esc(b.mode)} consultation</span></div></div></div><div class="card mt12"><div class="kv"><span class="key">When</span><span class="value">${formatDate(b.dateOffset)}</span></div><div class="kv"><span class="key">Time</span><span class="value">${esc(slotLabel(b.time))}</span></div><div class="kv"><span class="key">Location</span><span class="value">Online · Demo</span></div></div>${section('Before your appointment')}<div class="info-box">${I('info')} Keep your questions and relevant health records handy. In the real app, appointment links would only appear for supported confirmed consultations.</div><div class="action-stack mt20">${navBtn(`Preview ${esc(b.mode.toLowerCase())} consultation`,'consult')}${navBtn('Browse prescriptions','health','ghost')}</div><p class="notice mt20">A demonstration of the consultation experience. No real video connection or clinician.</p></div>`;}
function renderConsult(){
const b=s.booking;const d=b?(doctors.find(d=>d.id===b.doctorId)||doctors[0]):doctors[0];const mode=b?.mode||'Video';
if(mode==='Text')return `<div class="view" style="display:flex;flex-direction:column;min-height:100%">${head('Secure consultation',`<button class="button small-btn danger" data-action="end-call">End</button>`)}<div class="row" style="margin-bottom:18px"><img src="${d.photo}" alt="" style="width:43px;height:46px;object-fit:cover;border-radius:12px"/><div><strong class="small">${esc(d.name)}</strong><div class="tiny muted mt12" style="margin-top:4px">${I('lock',11)} Example secure text session</div></div></div><div class="info-box">${I('info')} This is a local message preview; no clinician is connected.</div><div class="secure-messages">${s.secureMessages.map(m=>`<div class="secure-bubble ${m.who==='user'?'you':''}">${esc(m.text)}</div>`).join('')}</div><form id="secure-chat-form" class="secure-composer"><input id="secure-message-input" placeholder="Type a message…" aria-label="Secure consultation message"/><button type="submit" aria-label="Send sample message">${I('send')}</button></form></div>`;
if(mode==='Voice')return `<div class="view" style="text-align:center"><div class="row between">${backButton()}<span class="pill-badge">${I('lock')} Demo voice consultation</span></div><div class="voice-portrait"><img src="${d.photo}" alt="Illustration of clinician"/></div><h1 class="page-h1">${esc(d.name)}</h1><p class="page-lead">Sample voice consultation · 05:24</p><div class="voice-bars">${[22,42,26,54,35,46,19,42,30,54,28,40,21].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="call-controls" style="margin:32px 0 24px"><div class="call-control"><button data-action="toggle-mic" class="${s.micOn?'':'off'}" aria-label="Toggle microphone">${I('mic')}</button><span>${s.micOn?'Mute':'Unmute'}</span></div><div class="call-control"><button data-action="end-call" class="end" aria-label="End sample consultation">${I('phone')}</button><span>End call</span></div></div><div class="info-box" style="text-align:left">${I('info')} No voice call or medical consultation is taking place in this prototype.</div></div>`;
return `<div class="view no-pad" style="background:var(--bg)"><div class="video-hero"><div class="call-top"><span class="call-pill">${I('lock',12)} Sample video session</span><span class="call-pill">${I('clock',12)} 05:24</span></div><img src="${d.photo}" alt="Illustration of sample clinician"/><div class="self-video">${s.cameraOn?'M':I('video',24)}<small>${s.cameraOn?'You':'Camera off'}</small></div></div><div class="call-bottom"><h2>${esc(d.name)}</h2><p>Secure consultation · Simulated session</p><div class="call-controls"><div class="call-control"><button data-action="toggle-mic" class="${s.micOn?'':'off'}" aria-label="Toggle microphone">${I('mic')}</button><span>${s.micOn?'Mute':'Unmute'}</span></div><div class="call-control"><button data-action="toggle-camera" class="${s.cameraOn?'':'off'}" aria-label="Toggle camera">${I('video')}</button><span>${s.cameraOn?'Camera':'Off'}</span></div><div class="call-control"><button data-action="end-call" class="end" aria-label="End sample consultation">${I('phone')}</button><span>End call</span></div></div><div class="info-box mt20" style="text-align:left">${I('info')} This is a visual demo of a consultation. There is no audio, video, chat connection or medical advice.</div></div></div>`;}
function renderAftercare(){return `<div class="view">${head('After your visit')}<div class="row" style="margin:9px 0 18px">${tag(`${I('check-circle')} Sample consultation complete`,'green')}</div><h1 class="page-h1">Your next steps,<br/>all in one place.</h1><p class="page-lead">An example of how clinician-issued aftercare instructions and prescriptions could appear here.</p><div class="card"><div class="row top"><span class="record-icon">${I('file-text')}</span><div><div class="strong small">Visit summary</div><div class="tiny muted" style="line-height:1.6;margin-top:5px">Example visit with Dr. Andrea Santos</div></div></div><div class="subtle-line"></div><p class="small" style="line-height:1.7;color:var(--muted);margin:0">Follow the treating clinician's actual instructions. Contact your healthcare professional if you have questions or your symptoms change.</p></div>${section('Your documents')}<button class="record-card" data-nav="prescription"><span class="record-icon">${I('file-text')}</span><span class="grow"><span class="small strong">Sample prescription</span><span class="tiny muted" style="display:block;margin-top:4px">Clinician-issued example · View details</span></span>${I('chevron-right')}</button><button class="record-card" data-nav="pharmacies"><span class="record-icon">${I('pill')}</span><span class="grow"><span class="small strong">Find prescribed medicine</span><span class="tiny muted" style="display:block;margin-top:4px">Compare sample pharmacy listings</span></span>${I('chevron-right')}</button><div class="info-box mt20">${I('shield-check')} E-JUAN would only display prescriptions issued by qualified clinicians, not prescriptions generated by Ask Juan.</div><div class="footer-actions">${navBtn('Go to My Health','health')}</div></div>`;}
function renderHealth(){return `<div class="view">${head('My health',`<button class="round-icon" data-nav="welcome" aria-label="Account">${I('user')}</button>`)}<h1 class="page-h1">Everything in<br/>one place.</h1><p class="page-lead">Find your care history and sample healthcare documents.</p>${section('Appointments','Details','appointment')}<button class="record-card" data-nav="appointment"><span class="record-icon">${I('calendar')}</span><span class="grow"><span class="small strong">${s.booking?'Booked consultation':'Example appointment'}</span><span class="tiny muted" style="display:block;margin-top:5px">${formatDate(s.booking?s.booking.dateOffset:4)} · ${s.booking?s.booking.time:'Start whenever you like'}</span></span>${I('chevron-right')}</button>${section('Prescriptions & medicines')}<button class="record-card" data-nav="prescription"><span class="record-icon">${I('file-text')}</span><span class="grow"><span class="small strong">Prescription wallet</span><span class="tiny muted" style="display:block;margin-top:5px">1 example prescription available</span></span>${I('chevron-right')}</button><button class="record-card" data-nav="scan"><span class="record-icon">${I('camera')}</span><span class="grow"><span class="small strong">Scan a prescription</span><span class="tiny muted" style="display:block;margin-top:5px">Upload, review and search</span></span>${I('chevron-right')}</button>${section('Your care journey')}<button class="record-card" data-nav="aftercare"><span class="record-icon">${I('heart')}</span><span class="grow"><span class="small strong">Example aftercare</span><span class="tiny muted" style="display:block;margin-top:5px">Visit notes and next steps</span></span>${I('chevron-right')}</button><div class="info-box mt20">${I('lock')} This is a fictional patient profile. No real health records or sensitive information are being stored.</div></div>`;}
function renderPrescription(){return `<div class="view">${head('Prescription wallet')}<h1 class="page-h1">Your prescriptions.</h1><p class="page-lead">Review clinician-issued documents and find participating pharmacies.</p><div class="rx-sheet"><div class="rx-top"><div><span class="pill-badge green">${I('check-circle')} Clinician-issued example</span><div class="small strong" style="margin-top:10px">Sample care record</div></div><div class="rx-mark">℞</div></div><div class="rx-body"><div class="kv"><span class="key">Clinician</span><span class="value">Dr. Andrea Santos</span></div><div class="kv"><span class="key">Patient</span><span class="value">Maria D. (demo)</span></div><div class="subtle-line"></div><div class="medicine-row"><h4>Paracetamol 500 mg</h4><p>Example medicine record; refer to the actual prescriber's instructions for appropriate use.</p></div><div class="tiny muted" style="padding-top:12px">Fictional illustration. Not valid for dispensing or medical use.</div></div></div><div class="action-stack mt20">${btn(`Find nearby pharmacies ${I('arrow-right')}`,'rx-to-pharmacy')}${navBtn('Scan another prescription','scan','ghost')}</div></div>`;}
function renderScan(){return `<div class="view">${head('Scan prescription')}<h1 class="page-h1">From prescription<br/>to pharmacy.</h1><p class="page-lead">Upload a prescription, check the extracted information, then look for a matching medicine.</p>${!s.scanDone?`<div class="scan-drop"><div class="scan-icon">${I('camera')}</div><h3>Add your prescription</h3><p>Take a photo or choose an image or PDF from your device.</p><button class="button small-btn" data-action="select-file">${I('upload')} Choose a file</button><div class="tiny muted mt12">${s.uploadName?esc(s.uploadName):'PNG, JPG or PDF · Demo only'}</div></div><div class="info-box mt20">${I('info')} Extracted text needs your review. A scan does not verify a prescription, dosage, medicine substitution, or dispensing eligibility.</div><div class="action-stack mt20">${btn('Preview scanned result','preview-scan','secondary')}</div>`:`<div class="row between" style="margin-bottom:15px">${tag(`${I('file-text')} Example extraction`)}<button class="text-button" data-action="reset-scan">Upload again</button></div><div class="scan-detail"><div class="row top"><div class="select-icon">${I('check-circle')}</div><div><div class="strong small">Review extracted fields</div><div class="tiny muted" style="line-height:1.6;margin-top:5px">These are editable demo values, not medically verified.</div></div></div><div class="form-field"><label for="scan-med">Medicine name</label><input id="scan-med" value="${esc(s.scanMedicine)}" autocomplete="off"/></div><div class="form-field"><label for="scan-strength">Strength shown on prescription</label><input id="scan-strength" value="${esc(s.scanStrength)}" autocomplete="off"/></div><div class="form-field"><label for="scan-qty">Quantity (if legible)</label><input id="scan-qty" value="${esc(s.scanQty)}" autocomplete="off"/></div></div><div class="info-box amber mt12">${I('alert-circle')} Please check these details against your original prescription. Similar medicine names are not necessarily interchangeable.</div><div class="footer-actions">${btn('Find matching pharmacies','scan-search')}</div>`}</div>`;}
function pharmacyStatus(p){if(s.stockScenario==='stale')return {label:'Stock not confirmed',type:'amber',fresh:'Last update unknown'};if(s.stockScenario==='available')return {label:'Sample stock reported',type:'green',fresh:'Sample update · recently'};return {label:p.status,type:p.id===1?'green':'amber',fresh:p.fresh};}
function pharmacyCard(p){const st=pharmacyStatus(p);return `<article class="pharmacy-card"><div class="pharmacy-head"><div class="grow"><div class="pharmacy-name">${esc(p.name)}</div><div class="pharmacy-meta">${I('map-pin')} ${esc(p.area)} · ${esc(p.distance)}</div></div><div class="location-icon">${I('pill')}</div></div><div class="row between mt12">${tag(st.label,st.type)}<span class="tiny muted">${esc(st.fresh)}</span></div><div class="stock-row"><div><div class="stock-price">${currency(p.price)} <small>/ sample unit</small></div><div class="tiny muted" style="margin-top:4px">Estimated listed price, not a quote</div></div><button class="button secondary small-btn" data-pharmacy="${p.id}">Details ${I('arrow-right')}</button></div></article>`;}
function renderPharmacies(){const ps=pharmacies.filter(p=>p.name.toLowerCase().includes('sample'));const hasSample=/^paracetamol\s*500\s*mg$/i.test(s.medicine.trim());return `<div class="view">${head('Find medicines',`<button class="round-icon" data-nav="scan" aria-label="Scan prescription">${I('camera')}</button>`)}<h1 class="page-h1">Find your medicine.</h1><p class="page-lead">Search sample listings at pharmacies around Davao City.</p><form id="medicine-search-form" class="input-wrap directory-search">${I('search')}<input name="query" aria-label="Search medicine" value="${esc(s.medicineQuery)}" placeholder="Medicine name or strength"/><button type="submit" style="border:0;background:none;padding:5px;color:var(--blue)" aria-label="Search medicine">${I('arrow-right',16)}</button></form><div class="row between mb20"><button class="chip" data-nav="scan">${I('camera')} Scan prescription</button><div class="toggle-pair"><button class="${!s.mapView?'active':''}" data-view="list">${I('list')} List</button><button class="${s.mapView?'active':''}" data-view="map">${I('map')} Map</button></div></div><div class="row between" style="margin-bottom:11px"><div class="small strong">Results for “${esc(s.medicine)}”</div></div>${hasSample?`<div class="row between" style="margin-bottom:15px"><span class="tiny muted">3 example pharmacy branches</span><select id="stock-select" aria-label="Sample inventory state" style="max-width:145px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--muted);padding:6px;font-size:10px"><option value="mixed" ${s.stockScenario==='mixed'?'selected':''}>Mixed sample stock</option><option value="available" ${s.stockScenario==='available'?'selected':''}>Reported stock</option><option value="stale" ${s.stockScenario==='stale'?'selected':''}>Unconfirmed stock</option></select></div>${s.mapView?`<div class="mock-map"><div class="map-water"></div><div class="map-park"></div><button class="map-pin one" data-pharmacy="1" aria-label="Downtown pharmacy">${I('pill')}</button><button class="map-pin two" data-pharmacy="2" aria-label="Bajada pharmacy">${I('pill')}</button><button class="map-pin three" data-pharmacy="3" aria-label="Matina pharmacy">${I('pill')}</button></div><div class="info-box mt12">${I('info')} This is an illustrative location view, not real map data or navigation.</div><div class="mt20">${pharmacyCard(ps[0])}</div>`:ps.map(pharmacyCard).join('')}<div class="info-box amber mt12">${I('alert-circle')} Availability, pricing and distance are fictional examples. Real stock must be confirmed directly with the pharmacy; prescription requirements still apply.</div>`:`<div class="empty-graphic">${I('pill')}</div><h2 class="empty-h">No sample listing for this medicine</h2><p class="empty-p">This offline prototype only contains one example medicine. It cannot verify real products or stock.</p>${btn('View the sample medicine','reset-medicine','secondary full')}`} </div>`;}
function renderPharmacyDetail(){const p=pharmacies.find(x=>x.id===s.pharmacyId)||pharmacies[0],st=pharmacyStatus(p);return `<div class="view">${head('Pharmacy details')}<div class="row" style="margin:8px 0 16px"><span class="record-icon">${I('pill')}</span><div><div class="tiny muted mb8">PARTICIPATING PHARMACY · EXAMPLE</div><h1 style="margin:0;font-size:20px;line-height:1.2;letter-spacing:-.6px">${esc(p.name)}</h1></div></div><div class="card"><div class="row">${I('map-pin',17)}<span class="small">${esc(p.area)}</span></div><div class="row mt12">${I('navigation',17)}<span class="small muted">Approx. ${esc(p.distance)} · Fictional distance</span></div></div>${section('Medicine listing')}<div class="card"><div class="row between"><div><div class="strong small">${esc(s.medicine)}</div><div class="tiny muted mt12" style="margin-top:5px">Verify exact product and prescription with pharmacist</div></div>${I('pill',21)}</div><div class="subtle-line"></div><div class="row between">${tag(st.label,st.type)}<strong style="font-size:19px">${currency(p.price)}</strong></div><div class="tiny muted mt12">${esc(st.fresh)} · Sample only</div></div><div class="info-box amber mt20">${I('info')} No live pharmacy integration exists in this demo. Do not travel or purchase medicines based on these listings.</div><div class="action-stack mt20">${btn('Contact branch (demo)','contact-demo')}${btn('Directions (demo)','directions-demo','ghost')}</div></div>`;}
function renderCoverageInfo(){return `<div class="view">${head('Care options')}<div class="row" style="margin-bottom:13px">${tag(`${I('info')} How funding works`,'neutral')}</div><h1 class="page-h1">Explore care first.<br/>Check benefits later.</h1><p class="page-lead">Everyone can ask Juan, find a doctor, and search medicines. Only selected, approved beneficiaries may receive an LGU-funded consultation under a participating program.</p><div class="benefit-row"><span class="benefit-icon">${I('stethoscope')}</span><div><h3>Standard consultations</h3><p>Choose a doctor and time, then review the disclosed fee.</p></div></div><div class="benefit-row"><span class="benefit-icon">${I('shield-check')}</span><div><h3>LGU-funded care</h3><p>A separate potential program for selected beneficiaries. Provider, service, entitlement and remaining budget checks are required. Any monthly limit is a proposal, not a confirmed benefit.</p></div></div><div class="benefit-row"><span class="benefit-icon">${I('heart-pulse')}</span><div><h3>PhilHealth YAKAP</h3><p>Guidance toward your applicable accredited primary-care clinic; not an automatic subsidy for all teleconsultations.</p></div></div><div class="info-box mt20">${I('info')} E-JUAN is still a product concept. No government funding, accredited clinic affiliation, or benefit eligibility is established by this demonstration.</div><div class="action-stack mt20">${navBtn('Find a doctor','directory')}${navBtn('Ask Juan for guidance','ask','secondary')}</div></div>`;}
function renderYakApNext(){return `<div class="view">${head('YAKAP care navigation')}<h1 class="page-h1">Start with your<br/>primary-care clinic.</h1><p class="page-lead">YAKAP is a distinct PhilHealth primary-care pathway, not a blanket discount on all online consultations.</p><div class="card"><div class="row top"><span class="record-icon">${I('shield-check')}</span><div><div class="small strong">What to check</div><div class="tiny muted mt12" style="line-height:1.8;margin-top:9px">Confirm your applicable accredited primary-care clinic, current program requirements, supported services, and the provider's appointment process.</div></div></div></div><div class="card mt12"><div class="row top"><span class="record-icon">${I('info')}</span><div><div class="small strong">What this app can show</div><div class="tiny muted mt12" style="line-height:1.8;margin-top:9px">In a connected version, E-JUAN could guide you toward verified clinic contact or coordination steps. No live eligibility or network information is available here.</div></div></div></div><div class="info-box amber mt20">${I('alert-circle')} PhilHealth verification is not the same as approval for a separate LGU-funded consultation.</div><div class="action-stack mt20">${btn('Continue with self-pay','coverage-self')}${navBtn('Return home','home','ghost')}</div></div>`;}
const renderers={describe:renderDescribe,coverageInfo:renderCoverageInfo,welcome:renderWelcome,home:renderHome,ask:renderAsk,intake:renderIntake,recommendation:renderRecommendation,emergency:renderEmergency,directory:renderDirectory,profile:renderProfile,coverage:renderCoverage,booking:renderBooking,review:renderReview,booked:renderBooked,appointment:renderAppointment,consult:renderConsult,aftercare:renderAftercare,health:renderHealth,prescription:renderPrescription,scan:renderScan,pharmacies:renderPharmacies,pharmacyDetail:renderPharmacyDetail,yakapNext:renderYakApNext};
const tabPages=new Set(['home','ask','directory','health','pharmacies']);
const labelMap={describe:'ASK JUAN / DESCRIBE CONCERN',coverageInfo:'CARE OPTIONS / INFORMATION',welcome:'WELCOME / INTRO',home:'HOME / OVERVIEW',ask:'ASK JUAN / START',intake:'ASK JUAN / GUIDED INTAKE',recommendation:'ASK JUAN / NEXT STEP',emergency:'URGENT CARE / SAFETY',directory:'FIND CARE / DISCOVER',profile:'FIND CARE / PROFILE',coverage:'CARE OPTIONS / ELIGIBILITY',booking:'BOOKING / SCHEDULE',review:'BOOKING / REVIEW',booked:'BOOKING / CONFIRMED',appointment:'MY HEALTH / APPOINTMENT',consult:'CONSULTATION / PREVIEW',aftercare:'AFTERCARE / SUMMARY',health:'MY HEALTH / RECORDS',prescription:'PRESCRIPTIONS / WALLET',scan:'PRESCRIPTIONS / UPLOAD',pharmacies:'MEDICINES / PHARMACIES',pharmacyDetail:'MEDICINES / BRANCH',yakapNext:'YAKAP / NAVIGATION'};
function render(scroll=true){if(!renderers[s.page])s.page='home';if(s.page==='directory'&&$('#doctor-search-form')){ $('#doctor-results').innerHTML=renderDirectoryResults();for(const [attribute,value,cls] of [['availability-filter',s.availabilityFilter,'active'],['filter',s.filter,'selected'],['care-mode',s.careMode,'selected']]){screen.querySelectorAll('[data-'+attribute+']').forEach(button=>button.classList.toggle(cls,button.getAttribute('data-'+attribute)===value));}}else screen.innerHTML=renderers[s.page]();tabs.hidden=!tabPages.has(s.page);if(!tabs.hidden){tabs.innerHTML=[['home','home','Home'],['ask','sparkles','Ask Juan'],['directory','stethoscope','Find Care'],['health','file-text','My Health']].map(([id,ic,t])=>`<button class="nav-item ${s.page===id||(s.page==='pharmacies'&&id==='health')?'active':''}" data-nav="${id}" aria-label="${t}" ${s.page===id?'aria-current="page"':''}>${I(ic)}<span>${t}</span></button>`).join('');}else tabs.innerHTML='';$('#screen-label').textContent=labelMap[s.page]||'E-JUAN';if(scroll)screen.scrollTop=0;document.title='E-JUAN · '+(labelMap[s.page]||'Care');}
function go(page){if(!renderers[page])return;if(s.page!==page)s.history.push(s.page);s.page=page;render();}
function back(){s.page=s.history.pop()||'home';render();}
let toastTimeout;
function toast(msg){toastNode.textContent=msg;toastNode.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>toastNode.classList.remove('show'),3300);}
function detectEmergency(t){return /\b(chest pain|can't breathe|cannot breathe|severe trouble breathing|unconscious|fainting|stroke|suicid(?:e|al)|heart attack)\b/i.test(t);}
function handleAsk(t){const txt=t.trim();if(!txt){toast('Enter a question or choose a suggestion.');return;}if(detectEmergency(txt)){s.concern=txt;go('emergency');return;}if(/\b(medicine|medication|pharmacy|drug|paracetamol|tablet)\b/i.test(txt)){s.medicineQuery=txt.match(/paracetamol/i)?'Paracetamol 500 mg':txt;s.medicine=s.medicineQuery;go('pharmacies');return;}if(/\b(find|book|see) (a )?doctor\b/i.test(txt)){s.availabilityFilter='now';go('directory');return;}s.concern=txt;s.intakeStep=0;s.answers={};s.askBusy=true;render();setTimeout(()=>{if(s.page==='ask'&&s.askBusy){s.askBusy=false;go('intake');}},550);}
function handleAction(action){switch(action){case'doctor-search-toggle':{s.doctorSearchOpen=!s.doctorSearchOpen;const form=$('#doctor-search-form'),field=$('#doctor-search-field'),button=form.querySelector('.directory-search-toggle');form.classList.toggle('is-open',s.doctorSearchOpen);field.hidden=!s.doctorSearchOpen;button.setAttribute('aria-expanded',String(s.doctorSearchOpen));button.setAttribute('aria-label',s.doctorSearchOpen?'Hide doctor search':'Open doctor search');if(s.doctorSearchOpen)$('#doctor-search-input').focus();break;}case'back':back();break;case'ask-error':s.askError=true;render();break;case'ask-retry':s.askError=false;render();toast('Ready to try again.');break;case'voice':toast('Voice input is a visual concept in this demo. Please type your message.');break;case'edit-answers':s.intakeStep=0;s.answers={};go('intake');break;case'emergency':go('emergency');break;case'share':toast('Profile sharing would be available in the real application.');break;case'clear-filters':s.filter='All';s.careMode='All';s.onlyAvailable=false;s.availabilityFilter='all';s.doctorQuery='';const input=$('#doctor-search-input');if(input)input.value='';render();break;case'coverage-self':s.coverage='self';go('review');break;case'coverage-self-review':s.coverage='self';go('review');break;case'to-coverage':if(!s.hasSelectedDoctor){toast('Choose a doctor first.');go('directory');return;}if(!getSlots(getDoctor(),s.dateOffset).includes(s.time)){toast('Choose an available time first.');return;}go('coverage');break;case'show-upcoming':s.matchWindow='all';render(false);break;case'yakap-next':go('yakapNext');break;case'to-review':if(!getSlots(getDoctor(),s.dateOffset).includes(s.time)){toast('Choose a valid available time.');go('booking');return;}go('review');break;case'confirm-booking':{if(!getSlots(getDoctor(),s.dateOffset).includes(s.time)){toast('That sample slot is no longer selected. Please choose another time.');go('booking');return;}const d=getDoctor(),free=s.coverage==='lgu'&&s.lguStatus==='approved';s.booking={doctorId:d.id,doctorName:d.name,dateOffset:s.dateOffset,time:s.time,mode:s.mode,fee:free?0:d.fee,consent:s.consent};go('booked');break;}case'toggle-mic':s.micOn=!s.micOn;render(false);break;case'toggle-camera':s.cameraOn=!s.cameraOn;render(false);break;case'end-call':go('aftercare');break;case'rx-to-pharmacy':s.medicine='Paracetamol 500 mg';s.medicineQuery=s.medicine;go('pharmacies');break;case'select-file':$('#prescription-file').click();break;case'preview-scan':s.scanDone=true;render();break;case'reset-scan':s.scanDone=false;s.uploadName=null;$('#prescription-file').value='';render();break;case'scan-search':s.scanMedicine=$('#scan-med').value.trim();s.scanStrength=$('#scan-strength').value.trim();s.scanQty=$('#scan-qty').value.trim();if(!s.scanMedicine){toast('Enter the medicine name first.');return;}s.medicine=(s.scanMedicine+' '+s.scanStrength).trim();s.medicineQuery=s.medicine;go('pharmacies');break;case'reset-medicine':s.medicine='Paracetamol 500 mg';s.medicineQuery=s.medicine;s.mapView=false;render();break;case'contact-demo':toast('No real branch contact number is connected.');break;case'directions-demo':toast('Real-world directions are not connected in this demo.');break;}}
// All clickable controls are functional demo actions; routing is preserved in the browser session.
document.addEventListener('pointerdown',ev=>{if(s.page==='directory'&&document.activeElement===$('#doctor-search-input')&&ev.target.closest('button[data-availability-filter],button[data-filter],button[data-care-mode]'))ev.preventDefault();});
document.addEventListener('click',(ev)=>{const b=ev.target.closest('button[data-nav],button[data-action],button[data-match-window],button[data-concern],button[data-availability-filter],button[data-quick-doctor],button[data-doctor],button[data-answer],button[data-filter],button[data-date],button[data-time],button[data-mode],button[data-coverage],button[data-lgu],button[data-view],button[data-pharmacy],button[data-starter],button[data-care-mode],button[data-available]');if(!b)return;
if(b.dataset.nav){go(b.dataset.nav);return;}
if(b.dataset.action){handleAction(b.dataset.action);return;}
if(b.dataset.doctor){selectDoctor(b.dataset.doctor);return;}if(b.dataset.quickDoctor){selectDoctor(b.dataset.quickDoctor,true);return;}if(b.dataset.concern){const area=$('#describe-input');if(area){area.value=b.dataset.concern;area.focus();}document.querySelectorAll('button[data-concern]').forEach(x=>x.classList.toggle('selected',x===b));return;}if(b.dataset.matchWindow){s.matchWindow=b.dataset.matchWindow;render(false);return;}if(b.dataset.availabilityFilter){s.availabilityFilter=b.dataset.availabilityFilter;render(false);return;}
if(b.dataset.answer){const answer=b.dataset.answer;if(s.intakeStep===2){if(['Chest pain','Difficulty breathing','Fainting or confusion'].includes(answer)){s.answers.warning=answer;go('emergency');return;}s.answers.warning=answer;go('recommendation');return;}s.answers[s.intakeStep===0?'person':'duration']=answer;s.intakeStep++;render();return;}
if(b.dataset.filter){s.filter=b.dataset.filter;render(false);return;}
if(b.dataset.careMode){s.careMode=b.dataset.careMode;render(false);return;}
if(b.dataset.available){s.onlyAvailable=!s.onlyAvailable;render(false);return;}
if(b.dataset.date!==undefined){s.dateOffset=Number(b.dataset.date);const times=getSlots(getDoctor(),s.dateOffset);if(!times.includes(s.time))s.time=times[0]||'';render(false);return;}
if(b.dataset.time){s.time=b.dataset.time;render(false);return;}
if(b.dataset.mode){s.mode=b.dataset.mode;render(false);return;}
if(b.dataset.coverage){s.coverage=b.dataset.coverage;render(false);return;}
if(b.dataset.lgu){s.lguStatus=b.dataset.lgu;render(false);return;}
if(b.dataset.view){s.mapView=b.dataset.view==='map';render(false);return;}
if(b.dataset.pharmacy){s.pharmacyId=Number(b.dataset.pharmacy);go('pharmacyDetail');return;}
if(b.dataset.starter){switch(b.dataset.starter){case'doctor':go('directory');break;case'medicine':go('pharmacies');break;case'unwell':go('describe');break;case'care':go('describe');break;}return;}
});
document.addEventListener('submit',(e)=>{if(e.target.id==='describe-form'){e.preventDefault();const txt=$('#describe-input').value.trim();if(txt.length<5){toast('Please describe your concern in a few words.');return;}if(detectEmergency(txt)){s.concern=txt;go('emergency');return;}s.concern=txt;s.intakeStep=0;s.answers={};go('intake');return;}if(e.target.id==='ask-form'){e.preventDefault();handleAsk($('#ask-input').value);}if(e.target.id==='doctor-search-form'){e.preventDefault();s.doctorQuery=e.target.elements.query.value.trim();render(false);$('#doctor-search-input').focus({preventScroll:true});}if(e.target.id==='secure-chat-form'){e.preventDefault();const input=$('#secure-message-input');const msg=input.value.trim();if(msg){s.secureMessages.push({who:'user',text:msg});s.secureMessages.push({who:'doctor',text:'Message received in this demo. A real clinician would respond here during a supported consultation.'});render(false);screen.scrollTop=screen.scrollHeight;}return;}if(e.target.id==='medicine-search-form'){e.preventDefault();const val=e.target.elements.query.value.trim();if(!val){toast('Type a medicine name first.');return;}s.medicineQuery=val;s.medicine=val;render(false);}});
document.addEventListener('change',(e)=>{if(e.target.id==='consent-box'){s.consent=e.target.checked;}if(e.target.id==='stock-select'){s.stockScenario=e.target.value;render(false);}if(e.target.id==='prescription-file'){const f=e.target.files&&e.target.files[0];if(f){s.uploadName=f.name;s.scanDone=true;render();toast('Showing editable sample extracted fields. No file data was uploaded.');}}});
document.addEventListener('keydown',(e)=>{if(e.key==='Enter'&&e.target.id==='ask-input'&&!e.shiftKey){e.preventDefault();handleAsk(e.target.value);}if(e.key==='Escape'&&['profile','coverage','booking','review','pharmacyDetail','scan','appointment'].includes(s.page))back();});
render();
})();
